package org.apache.parquet.crypto;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;
import org.apache.parquet.hadoop.metadata.ColumnPath;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

public class InternalFileDecryptorSetColumnCryptoMetadataTests {

  private static final byte[] FOOTER_KEY = new byte[16];
  private static final byte[] COLUMN_KEY = new byte[16];

  private static InternalFileDecryptor newDecryptor() {
    FileDecryptionProperties properties =
        FileDecryptionProperties.builder().withFooterKey(FOOTER_KEY).build();
    return new InternalFileDecryptor(properties);
  }

  private static InternalFileDecryptor newDecryptorWithColumnKey(String columnPath) {
    Map<ColumnPath, ColumnDecryptionProperties> columnKeys = new HashMap<>();
    ColumnPath path = ColumnPath.fromDotString(columnPath);
    columnKeys.put(
        path, ColumnDecryptionProperties.builder(path).withKey(COLUMN_KEY).build());

    FileDecryptionProperties properties =
        FileDecryptionProperties.builder()
            .withColumnKeys(columnKeys)
            .withCheckFooterIntegrity(false)
            .build();
    return new InternalFileDecryptor(properties);
  }

  private static void markFileCryptoMetadataProcessed(InternalFileDecryptor decryptor)
      throws ReflectiveOperationException {
    Field field = InternalFileDecryptor.class.getDeclaredField("fileCryptoMetaDataProcessed");
    field.setAccessible(true);
    field.setBoolean(decryptor, true);
  }

  @Test
  void rejectsColumnMetadataBeforeFileCryptoMetadataIsProcessed() {
    InternalFileDecryptor decryptor = newDecryptor();
    ColumnPath path = ColumnPath.fromDotString("plain.column");

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setColumnCryptoMetadata(path, false, false, null, 0));
  }

  @Test
  void createsAndReusesPlaintextColumnSetup() throws ReflectiveOperationException {
    InternalFileDecryptor decryptor = newDecryptor();
    markFileCryptoMetadataProcessed(decryptor);

    ColumnPath path = ColumnPath.fromDotString("customer.id");

    InternalColumnDecryptionSetup first =
        decryptor.setColumnCryptoMetadata(path, false, false, null, 3);

    assertFalse(first.isEncrypted());
    assertEquals(3, first.getOrdinal());
    assertNull(first.getDataDecryptor());
    assertNull(first.getMetaDataDecryptor());

    InternalColumnDecryptionSetup second =
        decryptor.setColumnCryptoMetadata(
            ColumnPath.fromDotString("customer.id"), false, false, null, 99);

    assertSame(first, second);
    assertEquals(3, second.getOrdinal());
  }

  @Test
  void rejectsReuseWithDifferentEncryptionFlag() throws ReflectiveOperationException {
    InternalFileDecryptor decryptor = newDecryptor();
    markFileCryptoMetadataProcessed(decryptor);

    ColumnPath path = ColumnPath.fromDotString("customer.ssn");
    decryptor.setColumnCryptoMetadata(path, false, false, null, 1);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setColumnCryptoMetadata(path, true, false, null, 1));
  }

  @Test
  void rejectsEncryptedColumnWhenFooterKeyIsMissing() throws ReflectiveOperationException {
    String columnPath = "encrypted.footer.column";
    InternalFileDecryptor decryptor = newDecryptorWithColumnKey(columnPath);
    markFileCryptoMetadataProcessed(decryptor);

    ColumnPath path = ColumnPath.fromDotString(columnPath);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setColumnCryptoMetadata(path, true, true, null, 2));
  }

  @Test
  void rejectsEncryptedColumnWhenColumnKeyIsMissing() throws ReflectiveOperationException {
    InternalFileDecryptor decryptor = newDecryptor();
    markFileCryptoMetadataProcessed(decryptor);

    ColumnPath path = ColumnPath.fromDotString("encrypted.column.key");

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setColumnCryptoMetadata(path, true, false, null, 4));
  }
}
